import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Card, Button, DatePicker, Alert, Space, Title, Text } from '../components/BasicUI';
import './Home.css';

const Home = () => {
  const [games, setGames] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [analyzing, setAnalyzing] = useState({});

  const fetchGames = async (date) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(`/api/games/today?date=${date}`);
      setGames(response.data.data || []);
    } catch (error) {
      setError(error.response?.data?.error || 'Error al cargar los partidos');
    } finally {
      setLoading(false);
    }
  };

  const analyzeGame = async (mlbId) => {
    setAnalyzing(prev => ({ ...prev, [mlbId]: true }));
    try {
      await axios.post(`/api/games/analyze/${mlbId}`);
      // Recargar partidos para mostrar el estado actualizado
      await fetchGames(selectedDate);
    } catch (error) {
      setError(error.response?.data?.error || 'Error al analizar el partido');
    } finally {
      setAnalyzing(prev => ({ ...prev, [mlbId]: false }));
    }
  };

  const handleDateChange = (date) => {
    setSelectedDate(date);
    fetchGames(date);
  };

  useEffect(() => {
    fetchGames(selectedDate);
  }, []);

  const formatTime = (time) => {
    if (!time) return 'TBD';
    try {
      return new Date(`2000-01-01T${time}`).toLocaleTimeString('es-ES', { 
        hour: '2-digit', 
        minute: '2-digit' 
      });
    } catch (error) {
      return time;
    }
  };

  const getTeamAbbreviation = (name) => {
    const words = name.split(' ');
    if (words.length === 1) return name.substring(0, 2).toUpperCase();
    return words.map(word => word[0]).join('').toUpperCase();
  };

  return (
    <div className="home-page">
      <Title level={1}>Partidos del Día</Title>

      <Space direction="vertical" size="large">
        {/* Filtros */}
        <Card title="Filtros">
          <Space wrap>
            <div>
              <Text>Fecha:</Text>
              <DatePicker
                value={selectedDate}
                onChange={handleDateChange}
                className="basic-date-picker"
              />
            </div>
          </Space>
        </Card>

        {/* Mensajes de error */}
        {error && (
          <Alert type="error" message="Error" description={error} />
        )}

        {/* Lista de partidos */}
        <div className="games-container">
          {loading ? (
            <div className="loading">
              <div className="spinner"></div>
              <Text>Cargando partidos...</Text>
            </div>
          ) : games.length > 0 ? (
            games.map((game) => (
              <div key={game.id} className="game-card">
                {/* Header del partido */}
                <div className="game-header">
                  <div className="game-teams">
                    {/* Equipo visitante */}
                    <div className="team-info">
                      <div className="team-logo">
                        {getTeamAbbreviation(game.away_team_name)}
                      </div>
                      <div className="team-name">{game.away_team_name}</div>
                      <div className="team-record">Record: 0-0</div>
                    </div>

                    {/* VS */}
                    <div className="vs-indicator">VS</div>

                    {/* Equipo local */}
                    <div className="team-info">
                      <div className="team-logo">
                        {getTeamAbbreviation(game.home_team_name)}
                      </div>
                      <div className="team-name">{game.home_team_name}</div>
                      <div className="team-record">Record: 0-0</div>
                    </div>
                  </div>

                  {/* Hora del partido */}
                  <div className="game-time">
                    {formatTime(game.game_time)}
                  </div>
                </div>

                {/* Ubicación */}
                <div className="game-location">
                  Estadio, Ciudad, País
                </div>

                {/* Información de pitchers (simulada) */}
                <div className="game-pitchers">
                  <div className="pitcher-info">
                    <div className="pitcher-name">Pitcher Visitante</div>
                    <div className="pitcher-stats">LZ #XX | 0-0, 0.00 ERA</div>
                  </div>
                  <div className="pitcher-info">
                    <div className="pitcher-name">Pitcher Local</div>
                    <div className="pitcher-stats">LD #XX | 0-0, 0.00 ERA</div>
                  </div>
                </div>

                {/* Acciones */}
                <div className="game-actions">
                  <Button
                    type={game.status === 'analyzed' ? 'success' : 'primary'}
                    onClick={() => analyzeGame(game.mlb_id)}
                    loading={analyzing[game.mlb_id]}
                    disabled={game.status === 'analyzed'}
                    className={`action-button ${game.status === 'analyzed' ? 'success' : 'primary'}`}
                  >
                    {game.status === 'analyzed' ? '✓ Analizado' : 'Analizar'}
                  </Button>

                  <Button
                    type="secondary"
                    className="action-button secondary"
                  >
                    Vista Previa
                  </Button>

                  <Button
                    type="secondary"
                    className="action-button secondary"
                  >
                    Detalles
                  </Button>
                </div>

                {/* Estado del análisis */}
                {game.status === 'analyzed' && (
                  <div className="analysis-status">
                    <div className="status-badge analyzed">
                      ✓ Análisis Completado
                    </div>
                  </div>
                )}
              </div>
            ))
          ) : (
            <Card title="No hay partidos">
              <Text>No se encontraron partidos para la fecha seleccionada.</Text>
            </Card>
          )}
        </div>
      </Space>
    </div>
  );
};

export default Home;
